def C(instructions, **criteria): return dict(type='choice', instructions=instructions, criteria=criteria)
def N(instructions): return dict(type='noul', instructions=instructions)
def S(instructions, *criteria): return dict(type='score', instructions=instructions, criteria=list(criteria))
def scenario(name, state, expected): return dict(name=name, state=state, expected=expected)
def add(slug,title,category,scene,summary,why,questions,scenarios,labels=None,policy=None,sources=('typesafe',),limit=None,pattern=None):
 key=next(iter(questions)); q=questions[key]
 labels=labels or ({k:k.replace('_',' ').title() for k in q['criteria']} if q['type']=='choice' else {})
 if policy is None:
  if q['type']=='choice': policy=dict(kind='choice',key=key)
  elif q['type']=='noul': policy=dict(kind='noul',key=key,low=.2,high=.8,yes='Flag for review',no='Continue')
  else: policy=dict(kind='score',key=key,max=len(q['criteria'])-1,threshold=(len(q['criteria'])-1)/2,high='Prioritize',low='Standard queue')
 D.append(dict(id=f'{len(D)+1:02d}-{slug}',title=title,category=category,scene=scene,summary=summary,why=why,questions=questions,scenarios=scenarios,labels=labels,policy=policy,sources=[dict(title=SOURCES[k][0],url=SOURCES[k][1]) for k in sources],limitation=limit or 'Synthetic examples demonstrate an integration pattern. Validate on representative labeled data before choosing a model or an operating threshold.',pattern=pattern or ('Atomic '+q['type'].title())))
