add('response-quality','Composite response quality','Agents & evaluation','judge','Score grounding and relevance separately, then combine in code.','An evaluation pipeline needs independent dimensions and explicit weights.',{'grounding':S('Is answer supported by reference?','Unsupported','Partially supported','Fully supported'),'relevance':S('Does answer address question?','Unrelated','Partial answer','Direct answer')},[scenario('Good answer',{'question':'When does support open?','reference':'Support opens at 09:00 UTC.','answer':'Support opens at 09:00 UTC.'},{'grounding':2,'relevance':2}),scenario('Off-topic answer',{'question':'When does support open?','reference':'Support opens at 09:00 UTC.','answer':'Our logo is blue.'},{'grounding':0,'relevance':0})],policy=dict(kind='composite',keys=['grounding','relevance'],weights=[.7,.3],max=2,threshold=1.5,high='Meets demo rubric',low='Needs review'),sources=('composite','evals'),pattern='Atomic Score + weighted code')
add('extraction-verifier','Structured extraction verifier','Data & extraction','judge','Verify a candidate extraction against source text before accepting it.','A cascade needs a pass-or-review signal, not regenerated extraction.',{'correct':N('Does the extracted object accurately reflect all stated fields in the source?')},[scenario('Matching record',{'source':'Order A17 contains two blue mugs.','extracted':{'order':'A17','item':'blue mugs','quantity':2}},{'correct':.99}),scenario('Wrong item',{'source':'Order A17 contains two blue mugs.','extracted':{'order':'A17','item':'red plates','quantity':2}},{'correct':.01})],policy=dict(kind='noul',key='correct',low=.2,high=.8,yes='Accept candidate',no='Escalate extraction'),sources=('cascade',))
add('email-span-extraction','Pre-parsed email selection','Data & extraction','route','Pick a billing email from candidates already found by a parser.','The caller needs an existing span ID instead of a newly generated email address.',{'span':C('Which candidate is explicitly identified as the billing contact?',email_1='First candidate',email_2='Second candidate',none='No billing email stated')},[scenario('Billing second',{'text':'Support: help@example.com. Billing: accounts@example.com.','candidates':['help@example.com','accounts@example.com']},{'span':'email_2'}),scenario('Billing first',{'text':'Billing: finance@example.com. Sales: buy@example.com.','candidates':['finance@example.com','buy@example.com']},{'span':'email_1'})],sources=('extraction',),limit='Candidates are supplied fixtures. A production parser should discover and validate spans in code.')
add('date-component-extraction','Date component extraction','Data & extraction','timeline','Identify a month and day from a bounded candidate set.','Typed choices can extract components while date validation and arithmetic stay in code.',{'month':C('Which month is explicitly named?',september='September',october='October',unknown='Neither named'),'day':C('Which day of month is explicitly named?',d12='12',d20='20',unknown='Neither named')},[scenario('September appointment',{'text':'The appointment is September 20.'},{'month':'september','day':'d20'}),scenario('October appointment',{'text':'The appointment is October 12.'},{'month':'october','day':'d12'})],sources=('dates',),pattern='Parallel bounded extraction',limit='Intentionally bounded to two months and days. No year is inferred; this does not parse arbitrary dates.')
add('document-layout','Document structure recovery','Data & extraction','batch','Classify text blocks as heading, paragraph or list item.','A renderer needs block types; it should preserve the original text.',{f'block_{i}':C(f'Classify blocks[{i}] by its document role.',heading='Short section title',paragraph='Explanatory prose',list='A list item') for i in range(3)},[scenario('Setup document',{'blocks':['Getting started','Install the package before running the server.','- Set your API key']},{'block_0':'heading','block_1':'paragraph','block_2':'list'}),scenario('Usage document',{'blocks':['Usage notes','- Start in preview mode','Live mode calls both providers.']},{'block_0':'heading','block_1':'list','block_2':'paragraph'})],sources=('format',),pattern='Parallel block classification')
add('entity-resolution','Knowledge graph entity alignment','Search & knowledge','graph','Choose whether two catalog records describe the same product.','A graph pipeline needs merge, separate or review rather than generated descriptions.',{'match':C('Do the two records identify the same product variant?',merge='Same product and same variant',separate='Different products or variants',review='Insufficient evidence')},[scenario('Same product',{'a':'Trail mug, 350 ml, blue, SKU M350-B','b':'Blue 350ml Trail Mug (M350-B)'},{'match':'merge'}),scenario('Different sizes',{'a':'Trail mug, 350 ml, blue','b':'Trail mug, 500 ml, blue'},{'match':'separate'})],sources=('entity',))
add('taxonomy-classification','Hierarchical product classification','Data & extraction','route','Choose a product leaf category inside a small taxonomy.','Catalog code needs a stable taxonomy ID, not an invented category.',{'category':C('Choose the most specific matching taxonomy leaf.',rainwear='Outdoors > Clothing > Rainwear',footwear='Outdoors > Footwear',audio='Electronics > Audio',other='Outside these leaves')},[scenario('Rain jacket',{'listing':'Light waterproof hiking shell with sealed seams.'},{'category':'rainwear'}),scenario('Headphones',{'listing':'Wireless noise-canceling headphones.'},{'category':'audio'})],sources=('hierarchy',),limit='Single-level slice of a hierarchy. This does not implement the full beam-search cookbook.')
add('contract-clause-triage','Contract clause triage','Operations','route','Route a clause to the relevant review checklist.','Review software needs a clause type before applying a checklist.',{'clause':C('Classify this clause topic, without giving legal advice.',confidentiality='Protecting confidential information',termination='Ending the agreement',payment='Fees and payment timing',other='Other subject')},[scenario('Confidentiality clause',{'text':'Each party shall protect the other party confidential information.'},{'clause':'confidentiality'}),scenario('Payment clause',{'text':'Invoices are payable within thirty days of receipt.'},{'clause':'payment'})],sources=('typesafe',),limit='Topic classification only; not legal advice or a finding of compliance.')
add('policy-compliance','Policy checklist screening','Trust & safety','gate','Check a draft against an explicit local publishing rule.','A publishing workflow needs a policy flag, not a general compliance essay.',{'violation':N('Does draft promise a guaranteed investment return? Policy prohibits guaranteed-return claims.')},[scenario('Prohibited promise',{'draft':'Invest here and you are guaranteed to double your money.'},{'violation':.99}),scenario('Risk-aware statement',{'draft':'Returns vary and losses are possible.'},{'violation':.01})],sources=('guardrails',),limit='Checks one fictional publishing rule. It does not determine legal or regulatory compliance.')
add('product-attribute','Product attribute extraction','Commerce','route','Select a material explicitly stated in a product listing.','A filter index needs a canonical material key instead of free-form text.',{'material':C('Which material is explicitly stated?',cotton='Cotton',wool='Wool',polyester='Polyester',unknown='None of these stated')},[scenario('Cotton shirt',{'listing':'A breathable shirt made from cotton.'},{'material':'cotton'}),scenario('Unspecified blend',{'listing':'Soft everyday shirt in a proprietary fabric blend.'},{'material':'unknown'})],sources=('extraction','typesafe'))
add('brand-safety','Ad placement brand safety','Commerce','gate','Check whether a placement conflicts with a stated brand rule.','An ad pipeline needs a suitability flag per placement.',{'unsuitable':N('Does placement promote gambling? This family brand excludes gambling placements.')},[scenario('Casino content',{'placement':'Live casino bonuses and betting tips.'},{'unsuitable':.99}),scenario('Family recipe',{'placement':'How to bake banana bread with children.'},{'unsuitable':.02})],sources=('typesafe',),limit='Illustrates one advertiser-defined rule; suitability is context-dependent.')
add('demand-features','Demand signal extraction','Commerce','gauge','Extract purchase intent and urgency as features for a separate forecaster.','A forecasting pipeline needs semantic numeric features alongside historical data.',{'intent':S('Rate explicit purchase intent.','Browsing only','Considering a purchase','Ready to buy'),'urgency':S('Rate expressed purchase urgency.','No deadline','Flexible near-term interest','Explicit immediate need')},[scenario('Immediate order',{'note':'We are ready to buy twenty units and need them this week.'},{'intent':2,'urgency':2}),scenario('Early browsing',{'note':'Just exploring products for an unspecified future project.'},{'intent':0,'urgency':0})],policy=dict(kind='composite',keys=['intent','urgency'],weights=[.6,.4],max=2,threshold=1.4,high='Strong demand signal',low='Weak demand signal'),sources=('features',),pattern='Semantic features + code composition',limit='This produces features, not a sales forecast or purchase probability.')
add('maintenance-triage','Maintenance report triage','Operations','route','Route equipment notes to a maintenance specialty.','A work-order system needs a trade or review queue.',{'trade':C('Which specialty matches the described symptom?',electrical='Power, wiring or electrical issue',mechanical='Moving parts, vibration or physical wear',facilities='Leaks, building fixtures or room issues',review='Unclear')},[scenario('Motor vibration',{'note':'The conveyor bearing grinds and vibrates during rotation.'},{'trade':'mechanical'}),scenario('Roof leak',{'note':'Rainwater is leaking through the warehouse ceiling.'},{'trade':'facilities'})],sources=('typesafe',),limit='Routes reports only. Does not diagnose equipment or authorize repairs.')
add('speculative-fanout','Speculative support fan-out','Agents & evaluation','route','Ask intent, urgency and refund reason together; read only the relevant branch.','One typed batch can prepare multiple branches without generating a workflow narrative.',{'intent':C('Which intent is expressed?',refund='Asks for money back',technical='Asks to fix an error',other='Neither'),'urgent':N('Does the message explicitly convey immediate urgency?'),'refund_reason':C('Which refund reason is stated?',duplicate='Duplicate payment',quality='Dissatisfied with quality',unknown='Not stated or not a refund request')},[scenario('Urgent duplicate',{'message':'I was billed twice. Refund the extra charge ASAP.'},{'intent':'refund','urgent':.99,'refund_reason':'duplicate'}),scenario('Technical question',{'message':'The export button shows an error. Can you help?'},{'intent':'technical','urgent':.1,'refund_reason':'unknown'})],sources=('fanout',),pattern='Choice + Noul + conditional code',limit='Questions are independent. Branch relevance is resolved in code; no question relies on another answer from the same call.')
# The course's running example: one exact state, three distinct question shapes.
d = D[0]
d.update(title='Support ticket: Choice, Noul & Score', summary='Ask three different questions about the same flight-refund ticket.', pattern='Choice + Noul + Score', primitiveExplorer=True)
d['questions'] = {
 'department': C('Which department should handle this ticket?', billing='Refunds, charges and payment issues', technical='Software bugs and integration failures', sales='New purchases and plan questions'),
 'refund': N('Does this message request a refund?'),
 'frustration': S('How frustrated does the customer sound?', 'Calm', 'Concerned', 'Very angry'),
}
d['scenarios'] = [
 scenario('Flight refund', 'My flight was cancelled and I need a refund before Friday, this is honestly ridiculous.', {'department':'billing','refund':.95,'frustration':1.65}),
 scenario('Calm sales question', 'Hello, could you tell me which plan includes team accounts? Thank you.', {'department':'sales','refund':.02,'frustration':.05}),
]
d['scenarios'][0]['previewAnswers'] = {
 'department': {'type':'choice','choice':'billing','probabilities':{'billing':.87,'technical':.13,'sales':0},'confidence':.805},
 'refund': {'type':'noul','noul':.95},
 'frustration': {'type':'score','score':1.65,'probabilities':{'0':.05,'1':.25,'2':.7},'legend':{'0':'Calm','1':'Concerned','2':'Very angry'},'confidence':.65},
}
d['labels'] = {'billing':'Billing','technical':'Technical','sales':'Sales'}
d['policy'] = {'kind':'choice','key':'department'}
d['limitation'] = 'The preview probabilities and confidence are illustrative, not API measurements. Noul 0.5 means uncertainty, not medium intensity. Score runs from 0 to 2 here and can fall between levels.'
next(d for d in D if d['id'].endswith('-skill-selection'))['policy'] = {'kind':'choice','key':'skill','require':'needed'}
for index, confidence, probabilities in [(0,.97,{'billing':.98,'technical':.01,'sales':.01}),(1,.4,{'billing':.25,'technical':.6,'sales':.15})]:
 next(d for d in D if d['id'].endswith('-confidence-escalation'))['scenarios'][index]['previewAnswers'] = {'team':{'type':'choice','choice':next(d for d in D if d['id'].endswith('-confidence-escalation'))['scenarios'][index]['expected']['team'],'confidence':confidence,'probabilities':probabilities}}
D[-1]['policy']={'kind':'fanout'}
next(d for d in D if d['id'].endswith('-date-component-extraction'))['policy']={'kind':'date'}
assert len(D)==50, len(D)
for d in D:
 path=ROOT/'use-cases'/d['id']; path.mkdir(parents=True,exist_ok=True)
 (path/'scenario.json').write_text(json.dumps(d,indent=2)+'\n')
 (path/'run.js').write_text("import { run } from '../../shared/cli.js';\nawait run(new URL('./scenario.json', import.meta.url));\n")
(ROOT/'shared'/'catalog.json').write_text(json.dumps([{k:d[k] for k in ['id','title','category','summary','scene']}|{'primitives':list(dict.fromkeys(q['type'] for q in d['questions'].values()))} for d in D],indent=2)+'\n')
print(f'Authored {len(D)} use cases / {sum(len(d["scenarios"]) for d in D)} fixtures')
